(()=>{'use strict';const A=[...document.querySelectorAll('.exercise')],K='latina-v2',w=(m,e)=>console.warn('[latina] '+m,e||''),get=()=>{try{return JSON.parse(localStorage.getItem(K)||'{}')}catch(e){w('storage',e);return{}}},save=()=>{try{localStorage.setItem(K,JSON.stringify(Object.fromEntries(A.map(x=>[x.dataset.id,{v:x.querySelector('textarea')?.value||''}]))))}catch(e){w('storage',e)}};let d=get();A.forEach(x=>{let t=x.querySelector('textarea');if(t)t.value=d[x.dataset.id]?.v||''});document.addEventListener('input',e=>{if(e.target.matches('textarea.answer'))save()});addEventListener('error',e=>w('error',e.error||e.message));addEventListener('unhandledrejection',e=>w('rejection',e.reason));if('serviceWorker'in navigator)addEventListener('load',()=>navigator.serviceWorker.register('./latina-sw.js').catch(e=>w('cache',e)),{once:true})})();